import { IEquipDTO } from '../../../@types/DTO/equip.dto.types';
import { IEquip, IEquipCategory } from '../../../@types/equip.types';

export function mapCategoriesToLabels(m: IEquipCategory) {
  return {
    value: m.id,
    label: m.name,
  };
}

export const mapEquipSuggest = (data: IEquipDTO): Partial<IEquip & { text: string }> => ({
  name: data.name,
  text: data.name,
  weight: +data.weight,
  value: +data.value,
  photo: data.photo,
  is_group: data.is_group == '1',
  is_musthave: data.is_musthave == '1',
  id_category: data.id_category ? +data.id_category : null,
});
